def do_limitu(ceny, limit):
    vybrane = []
    for cena in ceny:
        # Bod přerušení sem: kdy podmínka platí?
        if cena <= limit:
            vybrane.append(cena)
        print("Cena:", cena, "vybrané:", vybrane)
    return vybrane


# Zkuste v ladění také krok dovnitř funkce.
print(do_limitu([20, 80, 50], 50))
